from decimal import Decimal

def quote(fetch, amount):
    try:
        rate = Decimal(str(fetch()))
    except Exception:
        rate = Decimal("0.85")
    return {"status": "success", "currency": "GBP", "amount": str(Decimal(str(amount)) * rate)}

