import unittest
from transcripts import TranscriptBuffer

class Store:
    def __init__(self):
        self.records = {}
    async def put_if_absent(self, key, payload):
        if key in self.records and self.records[key] != payload:
            raise ValueError("Conflicting idempotency key")
        self.records.setdefault(key, payload)

class TranscriptTest(unittest.IsolatedAsyncioTestCase):
    async def test_basic_flush(self):
        store = Store()
        buffer = TranscriptBuffer(store, "test-owner", "test-session")
        buffer.append("turn-1", "hello")
        await buffer.flush("turn-1")
        self.assertEqual(store.records[("test-owner", "test-session", "turn-1")], ("hello",))

